window.TADABBUR_QASAS = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة القصص (٢٨)، سورةٌ مكّيّةٌ محورُها قصةُ موسى مفصّلةً من ولادتِه إلى نبوّتِه، وسنّةُ الله في تمكينِ المستضعفين وإهلاكِ المستكبرين (فرعونُ وقارون)، والردُّ على المشركين؛ فيها «ونريد أن نمن على الذين استضعفوا» وقصةُ قارون. بُدئت بـ«طسم». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":28,"name":"القصص","total_ayahs":88,"audio":[],"passages":[{"title":"مقدمةٌ وسنّةُ الله في المستضعفين والمستكبرين","range":[1,6],"theme":"آياتُ الكتابِ المبين، وقصةُ موسى وفرعونَ للعبرة، وطغيانُ فرعونَ واستضعافُه بني إسرائيل، وإرادةُ الله تمكينَ المستضعفين وإهلاكَ الطغاة","verses":[{"n":1,"reflection":{"text":"«طسم» — حروفٌ مقطّعةٌ من الحروفِ التي افتُتِحت بها بعضُ السورِ للتنبيهِ على إعجازِ القرآن، الله أعلمُ بمرادِه بها؛ ففي هذا التسليمُ لله في المتشابه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف تأويلَ ما لم يُبيَّن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في المتشابه."},"action":{"text":"سلّم لله فيما استأثر بعلمه من المتشابهِ كالحروفِ المقطّعة، ولا تتكلّف القولَ فيها بلا علم؛ واجعل تسليمك لما لم يتبيّن لك من المتشابهِ دأبك، مقبلًا على المحكمِ عاملًا به، فذلك سبيلُ الراسخين."}},{"n":2,"reflection":{"text":"«تلك آيات الكتاب المبين» — هذه آياتُ الكتابِ الموضِّحِ للحقِّ من الباطل؛ ففي هذا تعظيمُ القرآنِ ووضوحُ بيانه؛ فعظّم القرآنَ واتّبع بيانه، فهو كتابٌ مبينٌ لا لبسَ في هداه، تقوم به الحجّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المبينِ واتّباعُ بيانه."},"action":{"text":"عظّم القرآنَ واتّبع بيانه الموضِّحَ للحقّ، فهو كتابٌ مبينٌ لا لبسَ فيه؛ فاجعله إمامك في كلِّ أمرك، متدبّرًا لآياته، عاملًا بمحكمه، متلقّيًا هداه بالقبولِ والإذعان."}},{"n":3,"reflection":{"text":"«نتلو عليك من نبإ موسى وفرعون بالحق لقوم يؤمنون» — نقصّ عليك من خبرِ موسى وفرعونَ بالصدقِ لينتفع به المؤمنون؛ ففي هذا أنّ القصصَ للعبرةِ والانتفاع؛ فاقرأ قصصَ القرآنِ بقلبِ مؤمنٍ منتفعٍ لا قارئِ حكاياتٍ، فالمؤمنُ هو الذي يتّعظ بأخبارِ الأوّلين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قراءةُ القصصِ للعبرةِ والانتفاعِ لا للتسلية."},"action":{"text":"اقرأ قصصَ القرآنِ بقلبٍ مؤمنٍ يطلب العبرةَ والموعظةَ لا مجرّدَ الحكاية؛ فإنما تُقصّ «بالحق لقوم يؤمنون»؛ فتدبّر سننَ الله في نصرِ الحقِّ وأهله وإهلاكِ الظالمين؛ فمن قرأها معتبرًا انتفع، ومن قرأها لاهيًا حُرِم ثمرتها؛ فاجعل غايتك من القصصِ الاتّعاظَ والعمل."}},{"n":4,"reflection":{"text":"«إن فرعون علا في الأرض وجعل أهلها شيعا يستضعف طائفة منهم يذبح أبناءهم ويستحيي نساءهم إنه كان من المفسدين» — إنّ فرعونَ تكبّر وطغى في الأرض، وفرّق أهلها فرقًا، يستضعف بني إسرائيلَ فيذبّح أبناءهم ويستبقي نساءهم، إنه كان من المفسدين؛ ففي هذا بيانُ طغيانِ فرعونَ وتفريقِه وإفساده؛ فاحذر الطغيانَ والتفريقَ والإفساد، فتلك صفاتُ الجبابرة، وعاقبتُها الهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطغيانِ والتفريقِ والإفساد."},"action":{"text":"احذر صفاتِ الطغاةِ من العلوِّ في الأرضِ بغيرِ حق، وتفريقِ الناسِ وإذلالِ فئةٍ منهم، والإفسادِ في الأرض؛ فتلك سياسةُ فرعونَ التي أوردته الهلاك؛ فإن كان لك سلطانٌ فاعدل ولا تستضعف، ووحّد الصفَّ ولا تفرّقه، واسعَ في الإصلاحِ لا الإفساد؛ فالعاقبةُ للمصلحين لا للمستكبرين."}},{"n":5,"reflection":{"text":"«ونريد أن نمن على الذين استضعفوا في الأرض ونجعلهم أئمة ونجعلهم الوارثين» — ونريد أن نتفضّل على المستضعفين في الأرضِ فنجعلهم قادةً في الخيرِ ونورّثهم أرضَ الظالمين؛ ففي هذا سنّةُ الله في نصرِ المستضعفين وتمكينهم؛ فلا تيأس أيها المستضعفُ المظلوم، فسنّةُ الله أن يمكّن لأهلِ الحقِّ ويورّثهم، فاصبر واثبت على الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأملُ في نصرِ الله للمستضعفين وتمكينِهم."},"action":{"text":"لا تيأس إن كنت من المستضعفين المظلومين على حقّهم، فسنّةُ الله أن يمنَّ على المستضعفين فيجعلهم أئمةً وارثين، كما فعل ببني إسرائيل؛ فاصبر واثبت على الحقّ، وأحسن الظنَّ بالله؛ فالعاقبةُ للحقِّ وأهلِه مهما طال ليلُ الظلم؛ فالله ينصر عباده المستضعفين ويمكّن لهم متى صدقوا."}},{"n":6,"reflection":{"text":"«ونمكن لهم في الأرض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون» — ونمكّن للمستضعفين في الأرض، ونُري فرعونَ وهامانَ وجندهما على أيدي من استضعفوهم ما كانوا يحذرون من زوالِ ملكهم؛ ففي هذا أنّ حذرَ الظالمِ لا يردّ قدرَ الله؛ فاعلم أنّ ما قُدِّر واقعٌ لا يدفعه حذرُ الحاذرين، فتوكّل على الله ولا تخف تدبيرَ الظالمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ حذرَ الظالمِ لا يردُّ قدرَ الله."},"action":{"text":"أيقن بأنّ ما قدّره الله واقعٌ لا محالة، وأنّ حذرَ الظالمين وتدبيرَهم لا يردّ قضاءه؛ فقد أهلك فرعونَ على يدِ موسى الذي خاف منه وذبّح الأبناءَ حذرًا؛ فلا يخفك كيدُ الظالمين ولا قوّتهم، وتوكّل على الله؛ فتدبيرُه فوق تدبيرهم، وقدرُه غالبٌ على حذرهم، والعاقبةُ لأوليائه."}}]},{"title":"ولادةُ موسى وإلقاؤه في اليمِّ وردُّه إلى أمّه","range":[7,13],"theme":"وحيُ الله لأمِّ موسى بإلقائِه في اليمِّ ووعدُه بردِّه، والتقاطُ آلِ فرعونَ له، وربطُ الله على قلبِ أمّه، وردُّه إليها ليتحقّق وعدُ الله","verses":[{"n":7,"reflection":{"text":"«وأوحينا إلى أم موسى أن أرضعيه فإذا خفت عليه فألقيه في اليم ولا تخافي ولا تحزني إنا رادوه إليك وجاعلوه من المرسلين» — وألهمنا أمَّ موسى أن أرضعيه، فإذا خفت عليه فألقيه في النهرِ ولا تخافي ولا تحزني، إنا رادّوه إليك وجاعلوه من المرسلين؛ ففي هذا لطفُ الله بأمِّ موسى وتثبيتُها بالوعد؛ فثِق بوعدِ الله عند الشدائد، فمن ألقى أمره إلى الله في خوفه ردّ الله عليه أضعافَ ما خشي فقده، فالطاعةُ مع التوكّلِ سبيلُ الفرج.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ الله والتوكّلُ عليه عند الخوف."},"action":{"text":"إذا اشتدّ خوفك على من تحبّ أو على أمرٍ يهمّك، فألقِ أمرك إلى الله متوكّلًا كما ألقت أمُّ موسى ولدها في اليمِّ بأمرِ الله؛ وثِق بوعده «إنا رادوه إليك»؛ فمن سلّم أمره لله وأطاعه في خوفه، ردّ الله عليه خيرًا ممّا خشي فقده؛ فاجمع بين الأخذِ بالأسبابِ والتوكّلِ على الله، فالفرجُ من عنده."}},{"n":8,"reflection":{"text":"«فالتقطه آل فرعون ليكون لهم عدوا وحزنا إن فرعون وهامان وجنودهما كانوا خاطئين» — فأخذه آلُ فرعونَ من اليمِّ ليصيرَ لهم عدوًّا وحزنًا (وذلك عاقبةُ أمرهم)، إنّ فرعونَ وهامانَ وجندهما كانوا مخطئين؛ ففي هذا أنّ الله يجعل هلاكَ الظالمِ على يدِ من ربّاه؛ فاعلم أنّ تدبيرَ الله نافذٌ، فربّى فرعونُ عدوَّه في بيته، فما أحكم تدبيرَ الله وأعجزَ كيدَ المعاندين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بنفوذِ تدبيرِ الله وعجزِ كيدِ الظالمين."},"action":{"text":"تأمّل كيف يجري تدبيرُ الله فوق كيدِ الظالمين، حتى ربّى فرعونُ عدوَّه الذي يكون هلاكه على يديه في بيته «ليكون لهم عدوا وحزنا»؛ فأيقن بأنّ تدبيرَ الله نافذٌ لا يعجزه شيء، وكيدَ الظالمين مردودٌ عليهم؛ فلا تهبِ الظالمين، وثِق بأنّ الله محيطٌ بهم؛ فسلّم أمرك لمن بيده مقاليدُ كلِّ شيء."}},{"n":9,"reflection":{"text":"«وقالت امرأت فرعون قرت عين لي ولك لا تقتلوه عسى أن ينفعنا أو نتخذه ولدا وهم لا يشعرون» — وقالت امرأةُ فرعون: هو قرّةُ عينٍ لي ولك، لا تقتلوه عسى أن ينفعنا أو نتّخذه ولدًا، وهم لا يشعرون بعاقبةِ أمره؛ ففي هذا حفظُ الله لموسى بإلقاءِ محبّتِه في قلبِ امرأةِ فرعون؛ فاعلم أنّ الله يحفظ أولياءه بأسبابٍ لا تُحتسَب، فمن حفظه الله لم يضرّه كيدُ الخلق، فالتجئ إلى حفظِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بحفظِ الله لأوليائه بأسبابٍ لا تُحتسَب."},"action":{"text":"أيقن بأنّ الله يحفظ أولياءه ومن أراد بهم خيرًا بأسبابٍ خفيّةٍ لا تخطر ببال، حتى ألقى محبّةَ موسى في قلبِ امرأةِ فرعونَ فكانت سببَ نجاته؛ فالتجئ إلى حفظِ الله في كلِّ أمرك، وثِق بأنّ من حفظه الله لا يضرّه كيدُ الخلق؛ فاطلب رعايتَه وحفظه، فهو خيرُ حافظٍ وأرحمُ الراحمين."}},{"n":10,"reflection":{"text":"«وأصبح فؤاد أم موسى فارغا إن كادت لتبدي به لولا أن ربطنا على قلبها لتكون من المؤمنين» — وأصبح قلبُ أمِّ موسى فارغًا من كلِّ شيءٍ إلا ذكرَ موسى، حتى كادت تُظهِر أمره لولا أن ثبّتنا قلبها لتكون من المؤمنين بوعدِ الله؛ ففي هذا تثبيتُ الله لقلوبِ المؤمنين عند الفزع؛ فاسأل الله الثباتَ عند الشدائد، فالقلوبُ بيدِ الله يثبّتها ويربط عليها، فالجأ إليه ليربط على قلبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سؤالُ الله الثباتَ وربطَ القلبِ عند الشدائد."},"action":{"text":"اسأل الله أن يربط على قلبك ويثبّتك عند الشدائدِ والفزع، كما ربط على قلبِ أمِّ موسى فلم تُبدِ سرّها؛ فالقلوبُ بيدِ الله يقلّبها كيف يشاء؛ فإذا اضطرب قلبك بخوفٍ أو حزنٍ فالجأ إليه بالدعاءِ والثقةِ بوعده؛ فمن ربط الله على قلبه سكن واطمأنَّ وصبر، فالثباتُ نعمةٌ تُطلَب من مقلّبِ القلوب."}},{"n":11,"reflection":{"text":"«وقالت لأخته قصيه فبصرت به عن جنب وهم لا يشعرون» — وقالت أمُّ موسى لأختِه: تتبّعي أثره، فأبصرته عن بُعدٍ وهم لا يشعرون بأنها أختُه؛ ففي هذا الأخذُ بالأسبابِ مع التوكّل؛ فخذ بالأسبابِ الحكيمةِ ولا تناقض توكّلك، فأمُّ موسى وثقت بوعدِ الله ثم أرسلت أختَه تتحسّس خبره، فالتوكّلُ لا ينافي السعي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين التوكّلِ والأخذِ بالأسبابِ الحكيمة."},"action":{"text":"اجمع بين التوكّلِ على الله والأخذِ بالأسبابِ المشروعةِ الحكيمة، فلا يمنعك يقينك بوعدِ الله من السعي، كما أرسلت أمُّ موسى ابنتها تقصّ أثرَ أخيها بحذر؛ فالتوكّلُ الحقُّ يقارنه العمل؛ فبادر بالأسبابِ النافعةِ في أمورك، معتمدًا بقلبك على الله لا على السبب؛ فبهما يجتمع لك صدقُ التوكّلِ وحسنُ التدبير."}},{"n":12,"reflection":{"text":"«وحرمنا عليه المراضع من قبل فقالت هل أدلكم على أهل بيت يكفلونه لكم وهم له ناصحون» — ومنعناه من قبولِ ثديِ المراضعِ حتى ردَدناه لأمّه، فقالت أختُه: هل أدلّكم على أهلِ بيتٍ يكفلونه لكم وهم له ناصحون؟ ففي هذا تدبيرُ الله لردِّ موسى لأمّه؛ فاعلم أنّ الله يهيّئ الأسبابَ لتحقيقِ وعده، فما منعه من المراضعِ إلا ليردّه لأمّه، فثِق بأنّ الله يسوق أسبابَ الخيرِ لأوليائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يهيّئ الأسبابَ لتحقيقِ وعده."},"action":{"text":"أيقن بأنّ الله يهيّئ الأسبابَ ويسخّرها لتحقيقِ وعده لأوليائه، فحرّم على موسى ثديَ المراضعِ حتى يعود إلى أمّه كما وعدها؛ فإذا وعدك الله خيرًا فثِق بأنه سيسوق إليه أسبابه من حيث لا تحتسب؛ فلا تستبطئ الفرج، ولا تيأس من تحقّقِ وعده؛ فمدبّرُ الأمورِ يجعل العسيرَ يسيرًا، والأسبابَ طوعَ مشيئته."}},{"n":13,"reflection":{"text":"«فرددناه إلى أمه كي تقر عينها ولا تحزن ولتعلم أن وعد الله حق ولكن أكثرهم لا يعلمون» — فرددنا موسى إلى أمّه لتقرَّ عينها بلقائه ولا تحزن، ولتعلم أنّ وعدَ الله حقٌّ لا يتخلّف، ولكنّ أكثرَ الناسِ لا يعلمون؛ ففي هذا إنجازُ الله وعده لأمِّ موسى؛ فأيقن بأنّ وعدَ الله حقٌّ، فمن صبر وتوكّل رأى صدقَ وعدِ الله، فبعد الخوفِ أمنٌ وبعد الحزنِ قرّةُ عين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ وعدَ الله حقٌّ بعد الصبرِ والتوكّل."},"action":{"text":"أيقن بأنّ وعدَ الله حقٌّ لا يتخلّف، فمن صبر على البلاءِ وتوكّل على الله رأى صدقَ وعده كما ردّ الله موسى لأمّه فقرّت عينها؛ فبعد كلِّ خوفٍ أمنٌ، وبعد كلِّ حزنٍ فرج؛ فاصبر واثبت وأحسن الظنَّ بربّك عند شدّتك؛ فوعدُه بالفرجِ للصابرين حقٌّ، وأكثرُ الناسِ يجهلون هذه السنّةَ فيجزعون."}}]},{"title":"موسى يبلغ أشدّه ويقتل القبطيَّ ويخرج خائفًا","range":[14,21],"theme":"إيتاءُ موسى الحكمَ والعلم، وقتلُه القبطيَّ خطأً وتوبتُه، وتحذيرُ الناصحِ له، وخروجُه من المدينةِ داعيًا الله أن ينجّيه من الظالمين","verses":[{"n":14,"reflection":{"text":"«ولما بلغ أشده واستوى آتيناه حكما وعلما وكذلك نجزي المحسنين» — ولما بلغ موسى قوّتَه وكمالَ عقله آتيناه حكمةً وعلمًا، وكذلك نجزي المحسنين في أعمالهم؛ ففي هذا أنّ الإحسانَ سببٌ للعلمِ والحكمة؛ فأحسن عملك يرزقك الله علمًا وحكمة، فجزاءُ الإحسانِ توفيقٌ في الدينِ والعلم، فأتقن ما بين يديك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ سببٌ لنيلِ العلمِ والحكمةِ من الله."},"action":{"text":"أحسن في عملك وعبادتك ومعاملتك، فإنّ الإحسانَ سببٌ لتوفيقِ الله بالعلمِ والحكمةِ والفهم «وكذلك نجزي المحسنين»؛ فاجتهد في إتقانِ ما بين يديك وإخلاصِه لله؛ فمن أحسن العملَ فتح الله له أبوابَ العلمِ النافعِ والحكمةِ في القولِ والفعل؛ فالجزاءُ من جنسِ العمل، والإحسانُ يورث بصيرةً ورشدًا."}},{"n":15,"reflection":{"text":"«ودخل المدينة على حين غفلة من أهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغاثه الذي من شيعته على الذي من عدوه فوكزه موسى فقضى عليه قال هذا من عمل الشيطان إنه عدو مضل مبين» — ودخل موسى المدينةَ وقتَ غفلةِ أهلها فوجد رجلين يقتتلان: أحدهما من قومه والآخرُ من عدوّه، فاستغاثه الذي من قومه فوكزه موسى فقتله، فقال: هذا من عملِ الشيطان، إنه عدوٌّ مضلٌّ مبين؛ ففي هذا نسبةُ موسى الخطأَ للشيطانِ وعدمُ تبريره؛ فإذا زلّت بك قدمٌ فلا تبرّر خطأك، بل انسبه لنفسك والشيطان، واعترف به، فالاعترافُ أوّلُ التوبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ تبريرِ الخطأِ والاعترافُ به."},"action":{"text":"إذا أخطأت أو زلّت بك قدمٌ فلا تبرّر خطأك أو تزيّنه، بل اعترف به وانسبه إلى نفسك ووسوسةِ الشيطان كما قال موسى «هذا من عمل الشيطان»؛ فالاعترافُ بالذنبِ أوّلُ طريقِ التوبة؛ واحذر مكائدَ الشيطانِ الذي يجرّ إلى الزللِ ثم يزيّنه؛ فمن أنكر خطأه أصرَّ عليه، ومن اعترف به بادر بالتوبةِ والإصلاح."}},{"n":16,"reflection":{"text":"«قال رب إني ظلمت نفسي فاغفر لي فغفر له إنه هو الغفور الرحيم» — قال موسى: ربِّ إني ظلمتُ نفسي فاغفر لي، فغفر له، إنه هو الغفورُ الرحيم؛ ففي هذا مبادرةُ موسى بالتوبةِ والاعترافِ بالذنب؛ فبادر بالتوبةِ والاستغفارِ عند الزلل، واعترف بظلمك لنفسك، فالله غفورٌ رحيمٌ يقبل من تاب، فمن تاب تاب الله عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"المبادرةُ بالتوبةِ والاعترافِ بظلمِ النفس."},"action":{"text":"بادر بالتوبةِ والاستغفارِ فورَ وقوعِ الذنب، واعترف بظلمك لنفسك كما قال موسى «رب إني ظلمت نفسي فاغفر لي»؛ فالله الغفورُ الرحيمُ يقبل توبةَ من تاب ويغفر له؛ فلا تسوّف بالتوبة، ولا تقنط من المغفرة؛ فمن صدق في توبته واعترافه، غفر الله له وأبدله بالسيّئةِ حسنة؛ فأكثر من الاستغفارِ والرجوعِ إليه."}},{"n":17,"reflection":{"text":"«قال رب بما أنعمت علي فلن أكون ظهيرا للمجرمين» — قال موسى: ربِّ بما أنعمت عليّ من المغفرةِ وغيرها فلن أكون معينًا للمجرمين؛ ففي هذا أنّ شكرَ النعمةِ يكون بالبعدِ عن الإثمِ وأهله؛ فاجعل شكرك لنعمِ الله بألّا تعين على إثمٍ ولا تظاهر مجرمًا، فمن شكر النعمةَ وظّفها في الطاعةِ لا في معونةِ الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ بترْكِ إعانةِ المجرمين."},"action":{"text":"اشكر نعمَ الله عليك بألّا تجعلها عونًا على معصيةٍ أو ظلمٍ، ولا تكن ظهيرًا لمجرمٍ أو معينًا لظالمٍ على ظلمه؛ فمن شكر نعمةَ الله وظّفها في طاعته ونصرةِ الحقِّ لا في معونةِ الباطل؛ فاجعل مالك وجاهك وقوّتك في الخير؛ فإعانةُ المجرمين كفرانٌ للنعمة، وصرفُها في الطاعةِ شكرٌ يحفظها ويزيدها."}},{"n":18,"reflection":{"text":"«فأصبح في المدينة خائفا يترقب فإذا الذي استنصره بالأمس يستصرخه قال له موسى إنك لغوي مبين» — فأصبح موسى في المدينةِ خائفًا ينتظر الطلب، فإذا الذي استنصره بالأمسِ يستغيثه على آخر، فقال له موسى: إنك لبيّنُ الغواية؛ ففي هذا لومُ موسى لمن يجرّه إلى الفتن؛ فاحذر صحبةَ من يجرّك إلى المشاكلِ والفتن، ولُم من يوقعك في الحرجِ بتهوّره، فالعاقلُ يتجنّب المتهوّرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصاحبةِ من يجرُّ إلى الفتن."},"action":{"text":"احذر صحبةَ المتهوّرين الذين يجرّونك إلى المشاكلِ والفتنِ والخصومات، ولا تندفع في نصرةِ من عادته إثارةُ العداوات؛ فقد لام موسى مستصرخه «إنك لغوي مبين»؛ فانصر الحقَّ لا الأشخاص، وميّز بين النصرةِ المشروعةِ والانسياقِ وراء المتهوّرين؛ فالعاقلُ يزن عواقبَ نصرته، ولا يجعل نفسه أداةً لغواية الغاوين."}},{"n":19,"reflection":{"text":"«فلما أن أراد أن يبطش بالذي هو عدو لهما قال يا موسى أتريد أن تقتلني كما قتلت نفسا بالأمس إن تريد إلا أن تكون جبارا في الأرض وما تريد أن تكون من المصلحين» — فلما أراد موسى أن يبطش بالعدوِّ لهما قال القبطيُّ: يا موسى أتريد أن تقتلني كما قتلت نفسًا بالأمس؟ ما تريد إلا أن تكون جبارًا في الأرضِ ولا تريد الإصلاح؛ ففي هذا انتشارُ خبرِ خطأِ موسى وتأويلُه ضدّه؛ فاحذر أن يُساء تأويلُ فعلك، واحرص أن تكون من المصلحين لا من المتسلّطين، فالإصلاحُ غايةُ المؤمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على أن تكون من المصلحين لا الجبّارين."},"action":{"text":"احرص أن تكون من المصلحين في الأرض لا من الجبّارين المتسلّطين، فتلك تهمةٌ رُمِي بها موسى؛ واعلم أنّ الزللَ قد يُساء تأويله ويُشهَّر به؛ فاجعل مقصدك الإصلاحَ لا الانتقامَ أو التسلّط؛ ووازن أفعالك بميزانِ الحكمة؛ فالمصلحُ يبني ولا يهدم، ويرفق ولا يبطش إلا بحقّ؛ فكن من دعاةِ الإصلاحِ بالحكمةِ لا من أهلِ البطشِ والعلوّ."}},{"n":20,"reflection":{"text":"«وجاء رجل من أقصى المدينة يسعى قال يا موسى إن الملأ يأتمرون بك ليقتلوك فاخرج إني لك من الناصحين» — وجاء رجلٌ من أقصى المدينةِ مسرعًا قال: يا موسى إنّ الأشرافَ يتشاورون في قتلك فاخرج، إني لك من الناصحين؛ ففي هذا حفظُ الله لموسى بإرسالِ ناصح؛ فاعلم أنّ الله يقيّض لأوليائه من ينصحهم ويحفظهم، فاقبل النصيحةَ الصادقةَ ولو من واحد، واشكر الله على من ينصح لك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ النصيحةِ الصادقةِ وشكرُ الله على الناصحين."},"action":{"text":"اقبل النصيحةَ الصادقةَ ممّن ينصح لك ولو كان فردًا، وخذ بها إن دلّت على الخير كما قبل موسى نصيحةَ الرجل فخرج؛ واعلم أنّ الله يقيّض لأوليائه من يحفظهم وينصحهم؛ فاشكر الله على الناصحين الصادقين حولك، وكن أنت ناصحًا لإخوانك؛ فالنصيحةُ الصادقةُ من الدين، وقبولها من التوفيق، والدالُّ على الخيرِ كفاعله."}},{"n":21,"reflection":{"text":"«فخرج منها خائفا يترقب قال رب نجني من القوم الظالمين» — فخرج موسى من المدينةِ خائفًا ينتظر الطلب قائلًا: ربِّ نجّني من القومِ الظالمين؛ ففي هذا لجوءُ موسى إلى الله بالدعاءِ عند الخوف؛ فالجأ إلى الله بالدعاءِ عند الخوفِ والشدّة، فهو منجّي المستضعفين من الظالمين، فمن دعاه صادقًا نجّاه، فاجعل الدعاءَ ملاذك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاءِ عند الخوفِ والشدّة."},"action":{"text":"الجأ إلى الله بالدعاءِ الصادقِ عند الخوفِ والشدّةِ وطلبِ النجاةِ من الظالمين، كما دعا موسى «رب نجني من القوم الظالمين»؛ فالدعاءُ سلاحُ المؤمنِ وملاذه؛ فإذا أحاطت بك المخاوفُ فاطرح حاجتك بين يدي الله، واثقًا بإجابته؛ فهو منجّي المستضعفين، مغيثُ الملهوفين؛ فمن صدق في اللجوءِ إليه نجّاه وآواه، وأبدله بالخوفِ أمنًا."}}]},{"title":"موسى في مدين: السقيُ والزواجُ من ابنةِ شعيب","range":[22,28],"theme":"توجّهُ موسى إلى مدينَ وسقيُه للمرأتين، وإظهارُه فقرَه لله، ودعوةُ شعيبٍ له، وعرضُ تزويجِه على رعيِ ثماني حجج، وتوثيقُ العهد","verses":[{"n":22,"reflection":{"text":"«ولما توجه تلقاء مدين قال عسى ربي أن يهديني سواء السبيل» — ولما اتّجه موسى نحو مدينَ قال: عسى ربّي أن يهديني وسطَ الطريقِ وأقصدَه؛ ففي هذا تفويضُ موسى أمرَه لله وحسنُ ظنّه به؛ فأحسن ظنّك بالله وفوّض أمرك إليه في حيرتك، فمن توكّل على الله في طريقه هداه، فاطلب الهدايةَ منه في كلِّ أمرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ الأمرِ لله وحسنُ الظنِّ به عند الحيرة."},"action":{"text":"فوّض أمرك إلى الله وأحسن ظنّك به عند الحيرةِ وعدمِ وضوحِ الطريق، واطلب منه الهدايةَ إلى سواءِ السبيل كما فعل موسى وهو غريبٌ خائف؛ فمن توكّل على الله وأحسن الظنَّ به هداه ويسّر أمره؛ فاجعل دعاءك عند كلِّ التباسٍ «عسى ربي أن يهديني»؛ فالله لا يخيّب من رجاه، ويهدي من التجأ إليه، ويكفي من توكّل عليه."}},{"n":23,"reflection":{"text":"«ولما ورد ماء مدين وجد عليه أمة من الناس يسقون ووجد من دونهم امرأتين تذودان قال ما خطبكما قالتا لا نسقي حتى يصدر الرعاء وأبونا شيخ كبير» — ولما وصل موسى ماءَ مدينَ وجد جماعةً يسقون ماشيتهم، ووجد دونهم امرأتين تمنعان غنمهما، فقال: ما شأنكما؟ قالتا: لا نسقي حتى ينصرف الرعاءُ، وأبونا شيخٌ كبيرٌ لا يقدر؛ ففي هذا حرصُ المرأتين على العفّةِ والحياءِ في مزاحمةِ الرجال؛ فاحرص على العفّةِ والحياءِ في مخالطةِ الناس، وأعِن الضعيفَ المحتاج، فالمروءةُ في مساعدةِ الضعفاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحياءُ والعفّةُ في المخالطة، وإعانةُ الضعيف."},"action":{"text":"احرص على الحياءِ والعفّةِ في مخالطةِ الناسِ وتجنّبِ المزاحمة، كما ذادت المرأتان غنمهما حياءً عن مزاحمةِ الرعاء؛ وكن عونًا للضعيفِ والمحتاج؛ فالمروءةُ في مساعدةِ من لا يقدر؛ فإذا رأيت محتاجًا فبادر بعونه بعفّةٍ ونزاهةٍ لا تطلب جزاءً؛ فالحياءُ خيرٌ كلُّه، وإغاثةُ الملهوفِ من كرمِ الأخلاقِ ومكارمها."}},{"n":24,"reflection":{"text":"«فسقى لهما ثم تولى إلى الظل فقال رب إني لما أنزلت إلي من خير فقير» — فسقى موسى لهما ثم انصرف إلى الظلِّ فقال: ربِّ إني لما تنزّله إليّ من خيرٍ محتاجٌ فقير؛ ففي هذا إحسانُ موسى وإظهارُ فقره لله؛ فأحسن إلى المحتاجِ ابتغاءَ وجهِ الله لا جزاءً، وأظهر فقرك وحاجتك إلى ربّك، فالعبدُ فقيرٌ إلى الله في كلِّ حال، وأصدقُ الدعاءِ ما خرج من قلبٍ مفتقر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ لوجهِ الله وإظهارُ الفقرِ إليه."},"action":{"text":"أحسن إلى المحتاجين ابتغاءَ وجهِ الله لا طلبًا لجزاءٍ منهم، كما سقى موسى للمرأتين ثم لم يطلب أجرًا؛ وأظهر فقرك وحاجتك إلى الله وحده، فأنت فقيرٌ إليه في كلِّ نفَس؛ فاطرح حاجتك بين يديه بذلٍّ وافتقار «رب إني لما أنزلت إلي من خير فقير»؛ فأصدقُ الدعاءِ ما صدر عن قلبٍ منكسرٍ مفتقر؛ فالغنى كلُّه بيدِ الله، والعبدُ محتاجٌ إليه دومًا."}},{"n":25,"reflection":{"text":"«فجاءته إحداهما تمشي على استحياء قالت إن أبي يدعوك ليجزيك أجر ما سقيت لنا فلما جاءه وقص عليه القصص قال لا تخف نجوت من القوم الظالمين» — فجاءته إحدى المرأتين تمشي في حياءٍ وحشمةٍ قالت: إنّ أبي يدعوك ليكافئك على سقيك لنا، فلما جاءه وقصّ عليه خبره قال: لا تخف نجوت من القومِ الظالمين؛ ففي هذا حسنُ أدبِ المرأةِ في مشيها وكلامها؛ فاحرص على الحياءِ في الهيئةِ والقولِ لا سيّما النساء، وطمئن الخائفَ اللاجئ، فالحياءُ زينةٌ، وتأمينُ الخائفِ من الكرم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحياءُ في الهيئةِ والقول، وتطمينُ الخائف."},"action":{"text":"تحلَّ بالحياءِ في هيئتك ومشيك وكلامك لا سيّما في مخاطبةِ الجنسِ الآخر، فقد مدح الله المرأةَ «تمشي على استحياء»؛ وإذا لجأ إليك خائفٌ فطمئنه وآوه كما قال شعيبٌ لموسى «لا تخف نجوت»؛ فاجعل الحياءَ خُلقك، والرفقَ بالخائفِ دأبك؛ فالحياءُ شعبةٌ من الإيمان، وتأمينُ اللاجئِ الملهوفِ من كرمِ النفسِ ومروءتها."}},{"n":26,"reflection":{"text":"«قالت إحداهما يا أبت استأجره إن خير من استأجرت القوي الأمين» — قالت إحداهما: يا أبتِ استأجره للرعي، إنّ خيرَ من تستأجره القويُّ الأمين؛ ففي هذا أنّ خيرَ من يُوظَّف من جمع القوّةَ والأمانة؛ فاطلب في من توكّله القوّةَ والأمانةَ معًا، فبهما يُؤدّى العملُ ويُحفَظ، والكفاءةُ والنزاهةُ ركنا كلِّ ولاية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختيارُ العاملِ الجامعِ بين القوّةِ والأمانة."},"action":{"text":"اطلب فيمن تُوظِّفه أو تُوليه أمرًا صفتي القوّةِ (الكفاءةِ والقدرة) والأمانةِ (النزاهةِ والصدق) معًا، فهما معيارُ خيرِ الأجراءِ والولاة «إن خير من استأجرت القوي الأمين»؛ فلا تولِّ ضعيفًا عاجزًا ولو كان أمينًا، ولا خائنًا ولو كان قويًّا؛ فوازن بين الكفاءةِ والنزاهةِ في كلِّ اختيار؛ فبهذين تصلح الأعمالُ وتُحفَظ الأمانات."}},{"n":27,"reflection":{"text":"«قال إني أريد أن أنكحك إحدى ابنتي هاتين على أن تأجرني ثماني حجج فإن أتممت عشرا فمن عندك وما أريد أن أشق عليك ستجدني إن شاء الله من الصالحين» — قال شعيب: إني أريد أن أزوّجك إحدى ابنتيَّ على أن ترعى لي ثماني سنين، فإن أتممت عشرًا فتفضّلٌ منك، وما أريد أن أشقّ عليك، ستجدني إن شاء الله من الصالحين؛ ففي هذا حسنُ معاملةِ شعيبٍ ورفقُه ونسبتُه الصلاحَ لمشيئةِ الله؛ فعامل الناسَ برفقٍ ولا تشقَّ عليهم، وعلّق أمورك بمشيئةِ الله، وكن من الصالحين في معاملتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرفقُ في المعاملةِ وتعليقُ الأمورِ بمشيئةِ الله."},"action":{"text":"عامل من تتعامل معهم برفقٍ وسماحةٍ ولا تشقَّ عليهم كما قال شعيب «وما أريد أن أشق عليك»؛ واحرص على الصلاحِ في معاملاتك وعقودك؛ وعلّق أمورك المستقبلةَ بمشيئةِ الله «إن شاء الله»؛ فمن رفق في معاملته أحبّه الناس، ومن علّق أمره بمشيئةِ الله بُورِك له؛ فاجعل الرفقَ والصدقَ والاستثناءَ بمشيئةِ الله دأبك في كلِّ اتّفاق."}},{"n":28,"reflection":{"text":"«قال ذلك بيني وبينك أيما الأجلين قضيت فلا عدوان علي والله على ما نقول وكيل» — قال موسى: ذلك الاتّفاقُ بيني وبينك، أيَّ الأجلين أتممتُ فلا تبعةَ عليّ، والله على ما نقول شهيدٌ حفيظ؛ ففي هذا توثيقُ العهدِ والإشهادُ عليه بالله؛ فوثّق عهودك واجعل الله شهيدًا عليها، فمن أشهد الله على عهده حفظه وأدّاه، فالوفاءُ بالعهدِ من الأمانةِ والدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الوكيل"],"heart_state":{"text":"توثيقُ العهدِ والإشهادُ عليه بالله والوفاءُ به."},"action":{"text":"وثّق عهودك واتّفاقاتك ببيانٍ واضحٍ يقطع النزاع، واجعل الله شهيدًا ووكيلًا على ما تعاهدت عليه كما قال موسى «والله على ما نقول وكيل»؛ ثم أوفِ بعهدك ولا تنقضه؛ فمن استحضر شهادةَ الله على عهده حفظه وأدّاه بأمانة؛ فالوفاءُ بالعهودِ من خصالِ المؤمنين، ونقضُها من صفاتِ المنافقين؛ فاصدق في عهدك، والله رقيبٌ عليك."}}]},{"title":"النداءُ والنبوّةُ والآيتان وطلبُ العون","range":[29,35],"theme":"عودةُ موسى ونداؤه في البقعةِ المباركة، وتعريفُ الله نفسَه، وآيتا العصا واليد، وطلبُ موسى عونَ أخيه، ووعدُ الله بالنصرِ والغلبة","verses":[{"n":29,"reflection":{"text":"«فلما قضى موسى الأجل وسار بأهله آنس من جانب الطور نارا قال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بخبر أو جذوة من النار لعلكم تصطلون» — فلما أتمّ موسى المدّةَ وسار بأهله أبصر نارًا من جانبِ الطور، فقال لأهله: امكثوا إني أبصرتُ نارًا لعلّي آتيكم بخبرٍ أو قبسٍ تستدفئون به؛ ففي هذا بدءُ منعطفِ النبوّةِ من حاجةٍ دنيويةٍ عابرة؛ فاعلم أنّ الله يسوق أعظمَ الخيرِ من أبوابٍ لا تُحتسَب، فربّ حاجةٍ صغيرةٍ خبّأ الله خلفها فضلًا عظيمًا، فامضِ في سعيك محتسبًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يسوق الخيرَ من أبوابٍ لا تُحتسَب."},"action":{"text":"أيقن بأنّ الله يسوق أعظمَ الخيرِ من حيث لا تحتسب، فقد ذهب موسى يطلب نارًا لأهله فنال شرفَ النبوّة؛ فلا تحتقر سعيًا في حاجة، ولا تستصغر بابًا من أبوابِ الخير؛ فامضِ في طلبِ رزقك وقضاءِ حوائجك محتسبًا مسلّمًا لله؛ فقد يخبّئ لك خلف السببِ الصغيرِ فضلًا لا يخطر ببالك؛ فالتدبيرُ لله، والخيرُ بيده."}},{"n":30,"reflection":{"text":"«فلما أتاها نودي من شاطئ الواد الأيمن في البقعة المباركة من الشجرة أن يا موسى إني أنا الله رب العالمين» — فلما أتى النارَ نُودِي من شاطئِ الوادي الأيمنِ في البقعةِ المباركةِ من الشجرة: يا موسى إني أنا الله ربُّ العالمين؛ ففي هذا شرفُ التكليمِ وتعريفُ الله نفسَه؛ فاعرف ربّك بأنه اللهُ ربُّ العالمين، وعظّم مواطنَ ذكرِه، فمن عرف ربّه بالربوبيةِ الجامعةِ أفرده بالعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب العالمين"],"heart_state":{"text":"معرفةُ الله ربَّ العالمين وتعظيمُه."},"action":{"text":"اعرف ربّك بأنه اللهُ ربُّ العالمين، خالقُهم ومالكهم ومدبّرُ أمرهم؛ فمن عرفه بهذا أفرده بالعبادةِ والتعظيم؛ فعظّم الله في قلبك، واستحضر جلالَه عند ذكره؛ واعلم أنّ الربوبيةَ الجامعةَ توجب أن يُعبَد وحده لا شريكَ له؛ فاجعل معرفتك بربّك حاملةً لك على طاعته وإخلاصِ العبادةِ له."}},{"n":31,"reflection":{"text":"«وأن ألق عصاك فلما رآها تهتز كأنها جان ولى مدبرا ولم يعقب يا موسى أقبل ولا تخف إنك من الآمنين» — وأن ألقِ عصاك، فلما رآها تتحرّك كأنها حيّةٌ ولّى هاربًا ولم يرجع، فقيل: يا موسى أقبل ولا تخف إنك من الآمنين؛ ففي هذا تأمينُ الله لموسى؛ فاطمئنَّ في حضرةِ الله، فمن كان في جانبِ الله فهو آمنٌ، والخوفُ يزول بقربِ الله وتأمينه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأمنُ والطمأنينةُ في حضرةِ الله."},"action":{"text":"اطمئنَّ إذا كنت في طاعةِ الله وقربه، فإنه يؤمّن أولياءه «إنك من الآمنين»؛ فلا يستبد بك الخوفُ ما دمت في جانبِ الحقِّ ومعيّةِ الله؛ فإذا داهمك ما يفزعك فالجأ إلى الله يؤمّنك؛ فمن كان الله معه فلا خوفَ عليه ولا هو يحزن؛ فاجعل قربك من الله حصنك، فبه يزول الفزعُ ويحلّ الأمن."}},{"n":32,"reflection":{"text":"«اسلك يدك في جيبك تخرج بيضاء من غير سوء واضمم إليك جناحك من الرهب فذانك برهانان من ربك إلى فرعون وملئه إنهم كانوا قوما فاسقين» — أدخل يدك في جيبك تخرج بيضاءَ من غيرِ برص، وضمَّ إليك ذراعك من الفزعِ ليذهب، فهاتان آيتان من ربّك إلى فرعونَ وملئه، إنهم كانوا قومًا فاسقين؛ ففي هذا تأييدُ الله لموسى بالبرهانين، وعلاجُ الفزعِ بضمِّ الجناح؛ فأيقن بأنّ الله يؤيّد أولياءه بالبراهين، ويعلّمهم كيف يذهب فزعهم، فالله يكفي أولياءه ويسدّدهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بتأييدِ الله لأوليائِه وتسديدِهم."},"action":{"text":"أيقن بأنّ الله يؤيّد أولياءه بالبراهينِ والآياتِ ويسدّدهم كما أيّد موسى باليدِ والعصا وعلّمه علاجَ فزعه؛ فاعتمد على تأييدِ الله في حملِ الحقِّ ومواجهةِ الباطل؛ فمن نصر دينَ الله نصره الله وثبّته؛ فلا تهبِ الطغاةَ ولو عظُم سلطانهم، فإنهم قومٌ فاسقون؛ والبرهانُ والحجّةُ مع أهلِ الحقّ، والله ناصرهم ومسدّدهم."}},{"n":33,"reflection":{"text":"«قال رب إني قتلت منهم نفسا فأخاف أن يقتلون» — قال موسى: ربِّ إني قتلتُ منهم نفسًا فأخاف أن يقتلوني؛ ففي هذا صدقُ موسى في عرضِ حاله وخوفه على ربّه؛ فاعرض همومك ومخاوفك على الله بصدق، ولا تكتم حاجتك عنه، فمن بثَّ همّه إلى الله كفاه، فالصدقُ في الشكوى إليه بابُ العون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ في عرضِ الحالِ والمخاوفِ على الله."},"action":{"text":"اعرض همومك ومخاوفك وحاجاتك على الله بصدقٍ وانكسار، ولا تكتم عنه شيئًا فهو أعلمُ به منك؛ فقد بثَّ موسى خوفه إلى ربّه «فأخاف أن يقتلون»؛ فمن صدق في شكواه إلى الله وطلبِ عونه كفاه وأعانه؛ فاجعل الله موضعَ شكواك وبثِّ همّك؛ فبثُّ الحاجةِ إليه عبادةٌ وراحة، وكتمانها عنه لا يجدي، فهو مطّلعٌ على السرّ."}},{"n":34,"reflection":{"text":"«وأخي هارون هو أفصح مني لسانا فأرسله معي ردءا يصدقني إني أخاف أن يكذبون» — وأخي هارونُ أفصحُ مني لسانًا فأرسله معي عونًا يصدّقني، إني أخاف أن يكذّبوني؛ ففي هذا طلبُ موسى العونَ بأخيه واعترافُه بفضلِه؛ فاستعن بأهلِ الكفاءةِ في الحقّ، واعترف بفضلِ غيرك، فطلبُ العونِ في الخيرِ ليس نقصًا، والاعترافُ بمزيّةِ الآخرين من الإنصاف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعانةُ بأهلِ الكفاءةِ والاعترافُ بفضلهم."},"action":{"text":"استعن بأهلِ الكفاءةِ والقدرةِ في نصرةِ الحقِّ وحملِ أعبائه، ولا ترَ في طلبِ العونِ نقصًا، فقد طلب موسى عونَ أخيه؛ واعترف بفضلِ غيرك ومزيّته كما اعترف موسى لهارونَ بالفصاحة «هو أفصح مني لسانا»؛ فالإنصافُ يقتضي معرفةَ فضلِ أهلِ الفضل؛ فاجمع حولك أصحابَ الكفاءاتِ في الخير، وأنزل كلًّا منزلته، معترفًا بما وهبهم الله."}},{"n":35,"reflection":{"text":"«قال سنشد عضدك بأخيك ونجعل لكما سلطانا فلا يصلون إليكما بآياتنا أنتما ومن اتبعكما الغالبون» — قال الله: سنقوّيك بأخيك ونجعل لكما حجّةً وغلبةً فلا يصلون إليكما بأذًى، بآياتنا أنتما ومن اتبعكما الغالبون؛ ففي هذا وعدُ الله بالنصرِ والغلبةِ لأهلِ الحقّ؛ فاطمئنَّ إلى أنّ العاقبةَ لأهلِ الحقّ ومتّبعيهم، فبآياتِ الله وحجّته يغلب المؤمنون، فاثبت على الحقِّ واثقًا بنصرِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ العاقبةَ والغلبةَ لأهلِ الحقّ."},"action":{"text":"أيقن بأنّ العاقبةَ والغلبةَ لأهلِ الحقِّ ومن اتّبعهم «أنتما ومن اتبعكما الغالبون»؛ فاثبت على الحقِّ ولو كثُر أهلُ الباطلِ وقوي سلطانهم؛ فالله يشدّ أعضادَ أوليائه ويجعل لهم الحجّةَ والغلبة؛ فلا يهزّك ضعفُ أهلِ الحقِّ في عددٍ أو عُدّة، فالنصرُ بيدِ الله لا بالأسباب؛ فمن نصر دينَ الله واثقًا بوعده، غلب بآياتِ الله وبرهانه."}}]},{"title":"موسى وفرعون: التكذيبُ والكبرُ وهلاكُ الظالمين","range":[36,42],"theme":"تكذيبُ فرعونَ بدعوى السحر، وكبرُه وأمرُه ببناءِ الصرح، واستكبارُه وإنكارُه البعث، وإغراقُه وجعلُه إمامًا يدعو للنار، ولعنتُه في الدارين","verses":[{"n":36,"reflection":{"text":"«فلما جاءهم موسى بآياتنا بينات قالوا ما هذا إلا سحر مفترى وما سمعنا بهذا في آبائنا الأولين» — فلما جاءهم موسى بآياتنا الواضحاتِ قالوا: ما هذا إلا سحرٌ مختلَق، وما سمعنا بهذا في آبائنا الأوّلين؛ ففي هذا ردُّهم الحقَّ بالتقليدِ ودعوى السحر؛ فلا يصدّنك عن الحقِّ أنه مخالفٌ لما عليه الآباء، فالتقليدُ الأعمى حجّةُ المعاندين، والحقُّ يُتّبَع بالبرهانِ لا بالمألوف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ ردِّ الحقِّ بحجّةِ مخالفتِه للآباء."},"action":{"text":"لا تردَّ الحقَّ لأنه يخالف ما كان عليه آباؤك أو ما ألِفه الناس، فتلك حجّةُ المكذّبين «وما سمعنا بهذا في آبائنا الأولين»؛ فزِن كلَّ أمرٍ بميزانِ الوحيِ والبرهانِ لا بموروثِ العادة؛ فالحقُّ لا يبطل بقدمِ الباطلِ وكثرةِ أهله؛ فحرّر عقلك من أسرِ التقليدِ الأعمى، واتّبع الدليلَ حيث قادك؛ فمن قدّم الحقَّ على المألوفِ هُدِي، ومن آثر عادةَ آبائه ضلّ."}},{"n":37,"reflection":{"text":"«وقال موسى ربي أعلم بمن جاء بالهدى من عنده ومن تكون له عاقبة الدار إنه لا يفلح الظالمون» — وقال موسى: ربّي أعلمُ بمن جاء بالهدى من عنده، ومن تكون له العاقبةُ الحسنةُ في الدار، إنه لا يفلح الظالمون؛ ففي هذا ردُّ موسى الحكمَ إلى علمِ الله، وتقريرُ أنّ العاقبةَ للمهتدين لا للظالمين؛ فكِل الحكمَ بينك وبين خصومك إلى الله، واعلم أنّ العاقبةَ للمتّقين، وأنّ الظالمَ لا يفلح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ الحكمِ إلى الله واليقينُ بأنّ العاقبةَ للمهتدين."},"action":{"text":"كِل الحكمَ بينك وبين مخالفيك إلى الله العالمِ بالمحقِّ من المبطل «ربي أعلم بمن جاء بالهدى»؛ ولا تُطِل الجدالَ العقيمَ مع المعاند؛ وأيقن بأنّ العاقبةَ الحسنةَ للمهتدين المتّقين، وأنّ الظالمَ لا يفلح مهما علا؛ فاثبت على هداك، ودع أمرَ الفصلِ لله؛ فمن أيقن أنّ العاقبةَ للحقِّ صبر على الأذى، ولم يغرّه ظهورُ الباطلِ حينًا."}},{"n":38,"reflection":{"text":"«وقال فرعون يا أيها الملأ ما علمت لكم من إله غيري فأوقد لي يا هامان على الطين فاجعل لي صرحا لعلي أطلع إلى إله موسى وإني لأظنه من الكاذبين» — وقال فرعونُ لأشرافه: ما علمتُ لكم إلهًا غيري، فاصنع لي يا هامانُ آجرًّا وابنِ لي صرحًا عاليًا لعلّي أطّلع إلى إلهِ موسى، وإني لأظنّه كاذبًا؛ ففي هذا غايةُ كبرِ فرعونَ واستهزائه؛ فاحذر الكبرَ والاستهزاءَ بالحقّ، فتلك مقالةُ الطغاةِ التي أوردتهم الهلاك، والتوحيدُ لا يُعرَف بصرحِ الطين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من كبرِ الطغاةِ واستهزائهم بالحق."},"action":{"text":"احذر أشدَّ الحذرِ من الكبرِ والعلوِّ والاستهزاءِ بالحقّ وأهله، فتلك مقالةُ فرعونَ «ما علمت لكم من إله غيري» التي أوردته الهلاك؛ فتواضع لله واعترف بعبوديّتك؛ ولا تستخفَّ بالحقِّ أو تسخر من الدعاةِ إليه؛ فالكبرُ أصلُ كلِّ هلاك، والاستهزاءُ بالوحيِ جرأةٌ على الله؛ فالزم التواضعَ والإذعانَ للحقّ، فالعاقبةُ للمتواضعين لا للمستكبرين."}},{"n":39,"reflection":{"text":"«واستكبر هو وجنوده في الأرض بغير الحق وظنوا أنهم إلينا لا يرجعون» — وتكبّر فرعونُ وجنوده في الأرضِ بغيرِ حقّ، وظنّوا أنهم لا يُرجَعون إلينا للحساب؛ ففي هذا أنّ إنكارَ البعثِ أصلُ الطغيان؛ فاحذر أن ينسيك طولُ الأملِ لقاءَ الله، فمن أيقن بالرجوعِ إليه لم يتكبّر ولم يطغَ، فذكرُ المعادِ يكسر الكبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الرجوعِ إلى الله كاسرًا للكبرِ والطغيان."},"action":{"text":"استحضر دائمًا أنك راجعٌ إلى الله للحساب، فذلك يكسر كبرك ويردع طغيانك؛ فإنّ فرعونَ وجندَه استكبروا لمّا «ظنوا أنهم إلينا لا يرجعون»؛ فمن غفل عن المعادِ طغى وبغى، ومن أيقن به تواضع واستقام؛ فأكثر من ذكرِ الموتِ والبعثِ والحساب؛ فبه ينكسر الكبرُ، ويلين القلب، وتُتّقى المعاصي، ويُستعدُّ للقاءِ الله."}},{"n":40,"reflection":{"text":"«فأخذناه وجنوده فنبذناهم في اليم فانظر كيف كان عاقبة الظالمين» — فأخذنا فرعونَ وجنوده فألقيناهم في البحرِ مغرَقين، فانظر كيف كانت عاقبةُ الظالمين؛ ففي هذا عاقبةُ الطغيانِ والاستكبار؛ فاعتبر بعاقبةِ الظالمين، فمهما علا الظالمُ فمصيرُه الهلاك، فلا يغرّنك سلطانُ الظالمِ ولا إمهالُه، فالعاقبةُ وخيمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ الظالمين مهما علوا."},"action":{"text":"اعتبر بعاقبةِ الظالمين المستكبرين، فمهما علوا في الأرضِ وقوي سلطانهم فمصيرهم الهلاكُ والخزي كما أُغرِق فرعونُ وجنوده «فانظر كيف كان عاقبة الظالمين»؛ فلا يغرّنك سلطانُ ظالمٍ ولا إمهالُ الله له، فإنما يمهله ليزداد إثمًا؛ واحذر الظلمَ في نفسك؛ فالله يملي للظالمِ حتى إذا أخذه لم يفلته؛ فالعاقبةُ للمتّقين، والدمارُ للطغاة."}},{"n":41,"reflection":{"text":"«وجعلناهم أئمة يدعون إلى النار ويوم القيامة لا ينصرون» — وجعلناهم قادةً في الشرِّ يدعون أتباعهم إلى النار، ويومَ القيامةِ لا ينصرهم أحد؛ ففي هذا خطرُ أئمةِ الضلال؛ فاحذر أن تكون داعيًا إلى شرٍّ أو قدوةً في باطل، فوزرُك ووزرُ من تبعك، والدعاةُ إلى النارِ لا ناصرَ لهم يومَ القيامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تكون داعيًا أو قدوةً في الشرّ."},"action":{"text":"احذر أن تكون داعيًا إلى شرٍّ أو قدوةً في باطلٍ أو رأسًا في ضلالة، فإنّ أئمةَ الشرِّ «يدعون إلى النار» ويحملون أوزارهم وأوزارَ من اتّبعهم؛ فاجعل نفسك داعيًا إلى الخيرِ وقدوةً في الحق؛ فمن سنَّ سنّةً سيّئةً فعليه وزرها ووزرُ من عمل بها؛ فتخيّر أثرك في الناس؛ فالعاقبةُ للدعاةِ إلى الهدى، والخذلانُ لأئمةِ الردى."}},{"n":42,"reflection":{"text":"«وأتبعناهم في هذه الدنيا لعنة ويوم القيامة هم من المقبوحين» — وأتبعناهم في الدنيا لعنةً وطردًا، ويومَ القيامةِ هم من المطرودين المشوَّهين؛ ففي هذا أنّ الظالمَ يلحقه الخزيُ في الدنيا والآخرة؛ فاحذر الظلمَ فعقوبتُه لا تقتصر على الآخرة بل تلحقك في الدنيا لعنةً وذمًّا، فالسمعةُ السيّئةُ عقوبةٌ معجّلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ لأنه يورث الخزيَ في الدارين."},"action":{"text":"احذر الظلمَ كلَّه، فإنّ عقوبته لا تقتصر على الآخرةِ بل تلحق صاحبه في الدنيا لعنةً على الألسنةِ وذمًّا وسوءَ ذكرٍ كما لحق فرعونَ «وأتبعناهم في هذه الدنيا لعنة»؛ فمن ظلم لعنه الخلقُ وذمّوه، وطُرِد يومَ القيامةِ مع المقبوحين؛ فاجتنب الظلمَ لتنجو من خزيِ الدارين؛ فحسنُ الذكرِ في الدنيا نعمةٌ، وسوءُه عقوبةٌ معجّلةٌ قبل عذابِ الآخرة."}}]},{"title":"شهادةُ القرآنِ للنبيِّ بالغيبِ وقطعُ الأعذار","range":[43,50],"theme":"إيتاءُ موسى الكتابَ نورًا، وإخبارُ النبيِّ بغيبِ موسى دليلَ نبوّته، ورحمةُ إرسالِه لقطعِ الأعذار، وتناقضُ المعاندين، وذمُّ اتّباعِ الهوى","verses":[{"n":43,"reflection":{"text":"«ولقد آتينا موسى الكتاب من بعد ما أهلكنا القرون الأولى بصائر للناس وهدى ورحمة لعلهم يتذكرون» — ولقد آتينا موسى التوراةَ بعد أن أهلكنا الأممَ الأولى، جعلناها بصائرَ للناسِ وهدًى ورحمةً لعلّهم يتذكّرون؛ ففي هذا أنّ الكتبَ نورٌ وهدًى ورحمة؛ فاطلب البصيرةَ والهدى والرحمةَ في كتابِ الله، فمن تذكّر به أبصر طريقه، وكتابُ الله بصائرُ لمن تدبّره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ البصيرةِ والهدى والرحمةِ في كتابِ الله."},"action":{"text":"اطلب البصيرةَ والهدايةَ والرحمةَ في كتابِ الله، فقد جعله بصائرَ وهدًى ورحمةً لمن تذكّر؛ فأقبل على القرآنِ متدبّرًا متذكّرًا لتُبصر به طريقك، وتهتديَ به في ظلماتِ الحياة، وتنال رحمةَ الله؛ فمن جعل كتابَ الله إمامه أبصر الحقَّ وعمل به؛ فاجعل من تلاوتك تذكّرًا وعملًا، لا مجرّدَ حروفٍ تُقرأ."}},{"n":44,"reflection":{"text":"«وما كنت بجانب الغربي إذ قضينا إلى موسى الأمر وما كنت من الشاهدين» — وما كنت يا محمدُ حاضرًا بجانبِ الجبلِ الغربيِّ حين أوحينا إلى موسى الأمر، ولا كنت من الشاهدين لذلك؛ ففي هذا أنّ إخبارَ النبيِّ ﷺ بالغيبِ دليلُ نبوّته؛ فازدد يقينًا بصدقِ النبيِّ ﷺ، فما أخبر به من غيبِ الأوّلين لم يشهده ولا تعلّمه إلا وحيًا، فذلك برهانُ صدقه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الازديادُ يقينًا بصدقِ النبيِّ بإخبارِه بالغيب."},"action":{"text":"ازدد يقينًا بصدقِ النبيِّ ﷺ ونبوّته، فإخباره بأخبارِ الأمم السابقةِ التي لم يشهدها ولم يتعلّمها من أحدٍ دليلٌ على أنه موحًى إليه «وما كنت من الشاهدين»؛ فتأمّل هذا البرهان؛ فمن أين له علمُ هذه الأخبارِ الدقيقةِ لولا الوحي؟ فاثبت على الإيمانِ به، واتّبع ما جاء به؛ فصدقُ إخباره بالغيبِ حجّةٌ قاطعةٌ على صدقِ رسالته."}},{"n":45,"reflection":{"text":"«ولكنا أنشأنا قرونا فتطاول عليهم العمر وما كنت ثاويا في أهل مدين تتلو عليهم آياتنا ولكنا كنا مرسلين» — ولكنّا أنشأنا أممًا فطال عليهم الأمدُ فنسوا العهد، وما كنت مقيمًا في أهلِ مدينَ تتلو عليهم آياتنا، ولكنّا كنّا مرسلين لك بهذا الخبر؛ ففي هذا أنّ طولَ الأمدِ يورث الغفلة، وأنّ علمَ النبيِّ من الوحي؛ فجدّد عهدك مع الله ولا تدع طولَ الزمنِ يقسّي قلبك، وأيقن بأنّ ما جاء به النبيُّ وحيٌ لا اختلاق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تجديدُ العهدِ مع الله وعدمُ الغفلةِ بطولِ الأمد."},"action":{"text":"جدّد عهدك وصلتك بالله ولا تدع طولَ الزمنِ يقسّي قلبك ويورثك الغفلةَ كما طال الأمدُ على الأممِ قبلك فنسوا؛ فتعاهد إيمانك بالطاعةِ والذكرِ والتوبة؛ وأيقن بأنّ ما أخبر به النبيُّ ﷺ من أخبارِ مدينَ وغيرها وحيٌ من الله لا اطّلاعٌ ولا اختلاق؛ فاحذر قسوةَ القلبِ التي تأتي مع طولِ الأمل، وأحيِ قلبك بذكرِ الله وتدبّرِ كلامه."}},{"n":46,"reflection":{"text":"«وما كنت بجانب الطور إذ نادينا ولكن رحمة من ربك لتنذر قوما ما أتاهم من نذير من قبلك لعلهم يتذكرون» — وما كنت بجانبِ الطورِ حين نادينا موسى، ولكن أرسلناك رحمةً من ربّك لتنذر قومًا لم يأتهم نذيرٌ من قبلك لعلّهم يتذكّرون؛ ففي هذا أنّ إرسالَ الرسولِ رحمة؛ فاعرف نعمةَ الله عليك بالرسالةِ والقرآن، فما جاءك النذيرُ إلا رحمةً بك، فاشكر هذه النعمةَ باتّباعه والتذكّرِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ نعمةِ إرسالِ الرسولِ رحمةً واتّباعُه."},"action":{"text":"اعرف عظيمَ نعمةِ الله عليك بإرسالِ النبيِّ ﷺ وإنزالِ القرآن، فذلك رحمةٌ منه بك لتنذَر وتتذكّر «رحمة من ربك لتنذر»؛ فاشكر هذه النعمةَ باتّباعِ الرسولِ والعملِ بما جاء به، والتذكّرِ بالقرآن؛ فكم من أممٍ حُرِمت النذير؛ فأنت في نعمةٍ عظمى إذ بلغك الهدى؛ فقابلها بالإقبالِ والاتّباعِ لا بالإعراضِ والغفلة."}},{"n":47,"reflection":{"text":"«ولولا أن تصيبهم مصيبة بما قدمت أيديهم فيقولوا ربنا لولا أرسلت إلينا رسولا فنتبع آياتك ونكون من المؤمنين» — ولولا أنهم إذا أصابهم عذابٌ بذنوبهم يحتجّون قائلين: ربّنا هلّا أرسلت إلينا رسولًا فنتّبع آياتك ونؤمن، لعاجلناهم؛ ففي هذا أنّ الله أقام الحجّةَ بإرسالِ الرسلِ قطعًا للأعذار؛ فاعلم أنّ الله لا يعذّب حتى يُعذِر، فاحمده أن بلغتك الحجّة، ولا تجعل لنفسك عذرًا بعد بلوغِ الرسالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحمدُ لله على قطعِه الأعذارَ بإرسالِ الرسل."},"action":{"text":"احمد الله أنه أقام عليك الحجّةَ بإرسالِ الرسولِ وإنزالِ الكتابِ قطعًا لكلِّ عذر؛ فلم يبقَ لك حجّةٌ في التقصير بعد بلوغِ الهدى؛ فبادر بالإيمانِ والعملِ ولا تعتذر؛ فالله بعدله لا يعذّب أمّةً حتى يبعث فيها رسولًا؛ فإذ بلغتك الرسالةُ فقد لزمتك الحجّة؛ فلا تكن ممّن يتمنّى الرجعةَ بعد فواتِ الأوان، واعمل من الآن قبل أن تندم."}},{"n":48,"reflection":{"text":"«فلما جاءهم الحق من عندنا قالوا لولا أوتي مثل ما أوتي موسى أولم يكفروا بما أوتي موسى من قبل قالوا سحران تظاهرا وقالوا إنا بكل كافرون» — فلما جاءهم الحقُّ من عندنا قالوا: هلّا أُوتي محمدٌ مثلَ ما أُوتي موسى من الآيات؟ أولم يكفر أسلافهم بما أُوتي موسى؟ قالوا: التوراةُ والقرآنُ سحران تعاونا، وقالوا: إنا بكلٍّ كافرون؛ ففي هذا تناقضُ المعاندين وتلوّنُ حججهم؛ فلا يغرّنك تلوّنُ المعاندِ في حججه، فهو يطلب آيةً فإذا جاءت كفر، فالمعاندُ لا تُقنعه الآيات، إنما يُقنَع المنصف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ تناقضِ المعاندِ وأنه لا تُقنعه الآيات."},"action":{"text":"لا يغرّنك تلوّنُ المعاندِ وتناقضُ حججه، فهو يطلب آيةً، فإذا جاءت زعمها سحرًا، ثم يكفر بالجميع؛ فالمعاندُ لا تُقنعه البراهينُ لأنّ داءه الكبرُ لا الجهل؛ فلا تُتعب نفسك في إقناعِ من عزم على الردّ؛ ووجّه دعوتك للمنصفِ الطالبِ للحقّ؛ فمن أراد الهدى قبل أدنى بيّنة، ومن أراد العنادَ ردَّ أعظمَ الآيات؛ فاعرف طبائعَ الناسِ لتضع دعوتك موضعها."}},{"n":49,"reflection":{"text":"«قل فأتوا بكتاب من عند الله هو أهدى منهما أتبعه إن كنتم صادقين» — قل لهم: فأتوا بكتابٍ من عند الله أهدى من التوراةِ والقرآنِ أتّبعه إن كنتم صادقين في دعواكم؛ ففي هذا تحدٍّ للمعاندين بالبرهان؛ فتحدَّ المبطلَ ببرهانه، واطلب الدليلَ لكلِّ دعوى، فمن ادّعى فعليه البيان، والحقُّ يثبت بالبرهانِ لا بالدعوى المجرّدة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحدّي المبطلِ بالبرهانِ وطلبُ الدليلِ للدعوى."},"action":{"text":"تحدَّ المبطلَ المعاندَ بطلبِ البرهانِ على دعواه «فأتوا بكتاب من عند الله هو أهدى منهما»؛ ولا تقبل دعوى بلا دليل؛ فمن ادّعى شيئًا طُولِب ببيّنته؛ فاجعل الحقَّ والباطلَ يتميّزان بالحجّةِ لا بالصياحِ والدعوى؛ فإذا حاجّك مبطلٌ فاطلب منه الدليل، فإن عجز ظهر بطلانُ قوله؛ فالحقُّ منصورٌ بالبرهان، والباطلُ يفتضح عند طلبِ الحجّة."}},{"n":50,"reflection":{"text":"«فإن لم يستجيبوا لك فاعلم أنما يتبعون أهواءهم ومن أضل ممن اتبع هواه بغير هدى من الله إن الله لا يهدي القوم الظالمين» — فإن لم يجيبوك ببرهان فاعلم أنهم يتّبعون أهواءهم، ولا أضلَّ ممّن اتّبع هواه بلا هدًى من الله، إنّ الله لا يهدي القومَ الظالمين؛ ففي هذا أنّ اتّباعَ الهوى أصلُ الضلال؛ فاحذر اتّباعَ الهوى، واجعل الوحيَ إمامك لا هواك، فمن قاد هواه دينَه ضلّ، والهدى في اتّباعِ ما أنزل الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ الهوى وجعلُ الوحيِ إمامًا."},"action":{"text":"احذر اتّباعَ الهوى في دينك ومواقفك، فهو أصلُ كلِّ ضلال «ومن أضل ممن اتبع هواه بغير هدى من الله»؛ فاجعل الوحيَ إمامك وحاكمك لا هواك ورغبتك؛ فوازن آراءك ومواقفك بميزانِ الكتابِ والسنّة؛ فمن حكّم هواه في الحقِّ تاه وضلّ، ومن حكّم الوحيَ اهتدى؛ فراقب نفسك: أتتّبع دليلًا أم هوًى؟ فالنجاةُ في تقديمِ مرادِ الله على مرادِ النفس."}}]},{"title":"المنصفون من أهلِ الكتاب، والهدايةُ بيدِ الله","range":[51,56],"theme":"تتابعُ القرآنِ للتذكّر، وإيمانُ منصفي أهلِ الكتابِ وأجرُهم المضاعف، وإعراضُهم عن اللغو، وأنّ هدايةَ القلوبِ بيدِ الله لا بالنبيّ","verses":[{"n":51,"reflection":{"text":"«ولقد وصلنا لهم القول لعلهم يتذكرون» — ولقد تابعنا لهم القرآنَ وأنزلناه شيئًا بعد شيءٍ لعلّهم يتذكّرون؛ ففي هذا أنّ الله أتمَّ الحجّةَ بتتابعِ الوحي؛ فاغتنم تتابعَ آياتِ الله بالتذكّرِ والعمل، فما أنزل الله القرآنَ مفصّلًا إلا لتتذكّر وتتّعظ، فلا تدع الذكرى تمرّ بك بلا أثر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ تتابعِ آياتِ الله بالتذكّرِ والعمل."},"action":{"text":"اغتنم ما تتابع عليك من آياتِ الله وذكراه بالتذكّرِ والاتّعاظِ والعمل، فقد وصّل الله القولَ وتابعه رحمةً بك «لعلهم يتذكرون»؛ فلا تدع موعظةً تمرّ بك بلا أثر، ولا آيةً تتلوها بلا تدبّر؛ فكلّما بلغتك ذكرى فتفاعل معها بقلبك وعملك؛ فمن اغتنم الذكرى انتفع، ومن أعرض عنها بعد تتابعها كان أشدَّ حجّةً عليه."}},{"n":52,"reflection":{"text":"«الذين آتيناهم الكتاب من قبله هم به يؤمنون» — الذين آتيناهم الكتابَ من قبلِ القرآن (المنصفون منهم) هم بالقرآنِ يؤمنون لما وجدوه مصدّقًا لما عندهم؛ ففي هذا شهادةُ منصفي أهلِ الكتابِ للقرآن؛ فاعتبر بإيمانِ المنصفين من أهلِ العلم، فالحقُّ يعرفه أهلُ العلمِ المنصفون، ويؤمنون به إذا تبيّن لهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإيمانِ المنصفين من أهلِ العلم."},"action":{"text":"اعتبر بإيمانِ المنصفين من أهلِ الكتابِ بالقرآنِ لمّا عرفوا صدقه من كتبهم؛ فالحقُّ يقبله أهلُ العلمِ المنصفون متى تبيّن لهم؛ فاطلب الحقَّ عند أهله، ولا يمنعك سابقُ اعتقادٍ من قبولِ ما قام عليه الدليل؛ واقتدِ بمن آثر الحقَّ على الهوى؛ فالعلمُ النافعُ يقود صاحبه إلى الإذعانِ للحقّ؛ فكن منصفًا تقبل الحقَّ ممّن جاء به."}},{"n":53,"reflection":{"text":"«وإذا يتلى عليهم قالوا آمنا به إنه الحق من ربنا إنا كنا من قبله مسلمين» — وإذا يُتلى عليهم القرآنُ قالوا: آمنّا به، إنه الحقُّ من ربّنا، إنا كنّا من قبله منقادين للتوحيد؛ ففي هذا مبادرةُ المنصفين للإيمانِ عند سماعِ الحق؛ فبادر بالإيمانِ عند سماعِ الحق، ولا تتلكّأ، فالقلبُ السليمُ يسارع إلى قبولِ الحقِّ متى تبيّن، فكن من أهلِ المبادرةِ لا التردّد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى قبولِ الحقِّ عند سماعه."},"action":{"text":"بادر إلى قبولِ الحقِّ والإيمانِ به فورَ تبيّنه لك، ولا تتردّد ولا تتلكّأ، كما بادر المنصفون «قالوا آمنا به إنه الحق من ربنا»؛ فالقلبُ السليمُ يسارع إلى الحقِّ لا يعانده؛ فإذا وضح لك حقٌّ فأذعن له وأسلم؛ فالتسويفُ في قبولِ الحقِّ بابُ الحرمان؛ فكن من أهلِ المبادرةِ الذين يستجيبون لله ولرسوله إذا دعاهم لما يحييهم؛ فالسعادةُ في سرعةِ الإذعان."}},{"n":54,"reflection":{"text":"«أولئك يؤتون أجرهم مرتين بما صبروا ويدرءون بالحسنة السيئة ومما رزقناهم ينفقون» — أولئك المنصفون المؤمنون يُؤتَون أجرهم مرّتين بصبرهم على الحقّ، ويدفعون بالحسنةِ السيّئة، وينفقون ممّا رزقناهم؛ ففي هذا صفاتُ المؤمنين الصادقين وأجرُهم المضاعف؛ فادفع السيّئةَ بالحسنة، وأنفق ممّا رزقك الله، واصبر على الحقّ؛ فبهذه الخصالِ يُضاعَف الأجر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ ودفعُ السيّئةِ بالحسنةِ والإنفاق."},"action":{"text":"تحلَّ بخصالِ المؤمنين الصادقين: اصبر على الحقِّ والأذى في سبيله، وادفع إساءةَ المسيءِ إليك بالإحسانِ لا بالمثل، وأنفق ممّا رزقك الله في وجوهِ الخير؛ فبهذه الخصالِ يُضاعَف أجرك مرّتين؛ فإذا أساء إليك أحدٌ فقابله بالعفوِ والإحسان تكسب قلبه وأجرك؛ فالصبرُ والإحسانُ والبذلُ أخلاقُ أهلِ الإيمان، بها تُنال الدرجاتُ العلى."}},{"n":55,"reflection":{"text":"«وإذا سمعوا اللغو أعرضوا عنه وقالوا لنا أعمالنا ولكم أعمالكم سلام عليكم لا نبتغي الجاهلين» — وإذا سمعوا الباطلَ واللغوَ أعرضوا عنه وقالوا: لنا أعمالنا ولكم أعمالكم، سلامٌ عليكم متاركةً، لا نطلب صحبةَ الجاهلين؛ ففي هذا إعراضُ المؤمنين عن اللغوِ وترفّعُهم عن الجاهلين؛ فأعرض عن اللغوِ والباطل، وترفّع عن مجادلةِ السفهاء، وقابل جهلهم بالحلمِ والمتاركة، فالإعراضُ عن الجاهلين من العقلِ والوقار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإعراضُ عن اللغوِ والترفّعُ عن مجادلةِ الجاهلين."},"action":{"text":"أعرض عن اللغوِ والباطلِ وفضولِ الكلام، ولا تضيّع وقتك في مجالسِ السوء؛ وترفّع عن مجادلةِ السفهاءِ والجاهلين، وقابل جهلهم بالحلمِ والإعراضِ الجميل «سلام عليكم لا نبتغي الجاهلين»؛ فمن أعرض عن اللغوِ سلم دينه ووقته؛ ولا تنزل إلى مستوى الجاهلِ في السبابِ والجدال؛ فالإعراضُ عنهم عزّةٌ ووقار؛ فاصرف عمرك فيما ينفعك، ودع ما لا يعنيك."}},{"n":56,"reflection":{"text":"«إنك لا تهدي من أحببت ولكن الله يهدي من يشاء وهو أعلم بالمهتدين» — إنك يا محمدُ لا تهدي من أحببت هدايتَه، ولكنّ الله يهدي من يشاء، وهو أعلمُ بمن يستحقّ الهداية؛ ففي هذا أنّ هدايةَ التوفيقِ بيدِ الله وحده؛ فابذل السببَ في الدعوة، وسلّم أمرَ الهدايةِ لله، ولا تحزن على من لم يهتدِ، فليس إليك هداهم، إنما عليك البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الهادي"],"heart_state":{"text":"تسليمُ أمرِ الهدايةِ لله وبذلُ السببِ في الدعوة."},"action":{"text":"ابذل جهدك في دعوةِ من تحبّ إلى الحقّ، ثم سلّم أمرَ هدايتهم إلى الله، فإنّ هدايةَ التوفيقِ بيده وحده لا بيدك «إنك لا تهدي من أحببت»؛ فلا تحزن حزنًا يهلكك على من لم يهتدِ ولو كان أقربَ الناسِ إليك؛ فليس عليك إلا البلاغُ والدعاء؛ فادعُ وأحسن، وأكثر من الدعاءِ لهم بالهداية، وكِل أمرهم لله؛ فهو أعلمُ بمن يستحقّ الهدى، وأرحمُ بهم منك."}}]},{"title":"نعمةُ الحرمِ الآمن وسنّةُ الإهلاكِ بالعدل","range":[57,59],"theme":"اعتذارُ المشركين بخوفِ التخطّف والردُّ بنعمةِ الحرمِ الآمن، وإهلاكُ القرى الباطرة، وأنّ الله لا يهلك حتى يبعث رسولًا ولا يهلك إلا الظالمين","verses":[{"n":57,"reflection":{"text":"«وقالوا إن نتبع الهدى معك نتخطف من أرضنا أولم نمكن لهم حرما آمنا يجبى إليه ثمرات كل شيء رزقا من لدنا ولكن أكثرهم لا يعلمون» — وقالوا: إن نتّبع الهدى معك نُخطَف من أرضنا، أولم نجعل لهم حرمًا آمنًا تُجبى إليه ثمراتُ كلِّ شيءٍ رزقًا من عندنا؟ ولكنّ أكثرهم لا يعلمون؛ ففي هذا أنّ الخوفَ على الرزقِ من موانعِ الاستجابة؛ فلا يمنعك خوفُ فواتِ الرزقِ من اتّباعِ الحقّ، فالرزقُ بيدِ الله، ومن اتّقاه رزقه من حيث لا يحتسب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ ترْكِ الحقِّ خوفًا على الرزق."},"action":{"text":"لا تدع اتّباعَ الحقِّ والالتزامَ بالدينِ خوفًا على رزقك أو مكانتك أو مصلحتك الدنيوية، كما اعتذر المشركون بخوفِ التخطّف؛ فالرزقُ بيدِ الله وحده، وقد أمّنهم في حرمهم ورزقهم؛ فمن اتّقى الله وتمسّك بالحقِّ رزقه وكفاه من حيث لا يحتسب؛ فلا تُقدِّم مصلحةً موهومةً على طاعةِ الله؛ فطاعتُه سببُ البركةِ والأمن، والرزقُ مقسومٌ لا يزيده حرصٌ ولا ينقصه دين."}},{"n":58,"reflection":{"text":"«وكم أهلكنا من قرية بطرت معيشتها فتلك مساكنهم لم تسكن من بعدهم إلا قليلا وكنا نحن الوارثين» — وكم أهلكنا من قريةٍ أشِرت وطغت في معيشتها فبطرت النعمة، فتلك مساكنهم خاليةٌ لم تُسكَن بعدهم إلا قليلًا، وكنّا نحن الوارثين لها؛ ففي هذا خطرُ بطرِ النعمةِ والطغيانِ بها؛ فاحذر بطرَ النعمةِ والطغيانَ بها، واشكر الله عليها، فالبطرُ يزيل النعمَ ويورث الهلاك، والشكرُ يحفظها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من بطرِ النعمةِ وشكرُها لتدوم."},"action":{"text":"احذر بطرَ النعمةِ والأشرَ بها والطغيانَ في المعيشةِ ونسيانَ المنعم، فذلك سببُ زوالِ النعمِ وهلاكِ أهلها كما أُهلِكت القرى الباطرة؛ فقابل نعمَ الله بالشكرِ والتواضعِ واستعمالها في طاعته؛ فالشكرُ يحفظ النعمةَ ويزيدها، والبطرُ يمحقها ويجلب النقمة؛ فاستحضر أنّ ما بيدك من نعمةٍ منحةٌ من الله تُسأل عنها؛ فأدِّ شكرها، ولا تجعلها سبيلًا للطغيانِ والفساد."}},{"n":59,"reflection":{"text":"«وما كان ربك مهلك القرى حتى يبعث في أمها رسولا يتلو عليهم آياتنا وما كنا مهلكي القرى إلا وأهلها ظالمون» — وما كان ربّك ليهلك القرى حتى يبعث في عاصمتها رسولًا يتلو عليهم آياتنا، وما كنّا مهلكي القرى إلا وأهلها ظالمون؛ ففي هذا عدلُ الله ألّا يعذّب قبل الإعذارِ والإنذار؛ فاطمئنَّ إلى عدلِ الله، واعلم أنه لا يهلك إلا الظالمين بعد إقامةِ الحجّة، فلا يظلم ربّك أحدًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ لعدلِ الله الذي لا يهلك إلا بعد الإعذار."},"action":{"text":"اطمئنَّ إلى كمالِ عدلِ الله، فإنه لا يهلك قريةً حتى يبعث فيها رسولًا يقيم الحجّة، ولا يهلك إلا الظالمين «إلا وأهلها ظالمون»؛ فاحمد الله على عدله، وعلى بلوغِ الحجّةِ إليك؛ ولا تظنَّ بربّك ظلمًا، فما أصاب أحدًا إلا بذنبه بعد الإعذار؛ فبادر بالإيمانِ والطاعةِ ما دمت في مهلة؛ فمن ظلم بعد قيامِ الحجّةِ استحقّ العقوبة، ومن آمن وأصلح نجا برحمةِ الله."}}]}],"coverage":{"covered":59,"total":88}};
